import{_ as d,o as e,c as r,a2 as o}from"./chunks/framework.Dx-TCpNt.js";const u=JSON.parse('{"title":"键盘快捷键","description":"一页汇总所有按键和鼠标手势。焦点在文本输入框内时，单键快捷键会被忽略，因此写笔记不会写到一半突然换视图。","frontmatter":{"description":"一页汇总所有按键和鼠标手势。焦点在文本输入框内时，单键快捷键会被忽略，因此写笔记不会写到一半突然换视图。"},"headers":[],"relativePath":"zh/guide/shortcuts.md","filePath":"zh/guide/shortcuts.md","lastUpdated":1794779651000}'),a={name:"zh/guide/shortcuts.md"};function c(l,t,h,i,n,s){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="键盘快捷键" tabindex="-1">键盘快捷键 <a class="header-anchor" href="#键盘快捷键" aria-label="Permalink to &quot;键盘快捷键&quot;">​</a></h1><p>一页汇总所有按键和鼠标手势。焦点在文本输入框内时，单键快捷键会被忽略，因此写笔记不会写到一半突然换视图。</p><h2 id="这一页解决什么问题" tabindex="-1">这一页解决什么问题 <a class="header-anchor" href="#这一页解决什么问题" aria-label="Permalink to &quot;这一页解决什么问题&quot;">​</a></h2><p>快捷键分散在图库、切格工作台、对照阅读和笔记编辑器里。与其在各个视图里到处翻找，不如把这一页放在手边，或者打印出来贴在显示器旁边。</p><h2 id="全局" tabindex="-1">全局 <a class="header-anchor" href="#全局" aria-label="Permalink to &quot;全局&quot;">​</a></h2><table tabindex="0"><thead><tr><th>按键</th><th>操作</th></tr></thead><tbody><tr><td><code>[</code></td><td>上一页（可跨话）。</td></tr><tr><td><code>]</code></td><td>下一页（可跨话）。</td></tr><tr><td><code>P</code></td><td>切换到切格工作台。</td></tr><tr><td><code>C</code></td><td>切换到对照阅读。</td></tr><tr><td><code>S</code></td><td>显示或隐藏图库侧栏。</td></tr><tr><td><code>N</code></td><td>显示或隐藏笔记栏。</td></tr><tr><td><code>E</code></td><td>打开导出对话框（有打开的页面时）。</td></tr><tr><td><code>?</code></td><td>打开快捷键与操作帮助。</td></tr><tr><td><code>Ctrl+Z</code></td><td>撤销上一步分格改动。</td></tr><tr><td><code>Ctrl+Shift+Z</code></td><td>重做。</td></tr><tr><td><code>Ctrl+Y</code></td><td>重做（另一种）。</td></tr></tbody></table><h2 id="文件" tabindex="-1">文件 <a class="header-anchor" href="#文件" aria-label="Permalink to &quot;文件&quot;">​</a></h2><table tabindex="0"><thead><tr><th>按键</th><th>操作</th></tr></thead><tbody><tr><td><code>Ctrl+O</code></td><td>打开工程文件（<code>.mnproj</code>）。</td></tr><tr><td><code>Ctrl+S</code></td><td>保存当前页。</td></tr><tr><td><code>Ctrl+Shift+S</code></td><td>另存为工程。</td></tr></tbody></table><p>这些文件快捷键在输入时也有效，与桌面应用一致。</p><h2 id="切格工作台" tabindex="-1">切格工作台 <a class="header-anchor" href="#切格工作台" aria-label="Permalink to &quot;切格工作台&quot;">​</a></h2><table tabindex="0"><thead><tr><th>按键 / 手势</th><th>操作</th></tr></thead><tbody><tr><td>拖动框体</td><td>移动分格。</td></tr><tr><td>拖动角点或边缘手柄</td><td>八向缩放。</td></tr><tr><td>双击空白处</td><td>添加一个默认分格。</td></tr><tr><td>在空白处拖拽</td><td>框选一个分格。</td></tr><tr><td><code>Shift</code> + 拖拽</td><td>把新分格约束为正方形。</td></tr><tr><td><code>Alt</code> + 拖拽</td><td>关闭吸附。</td></tr><tr><td><code>Ctrl</code> 点击 / <code>Shift</code> 点击</td><td>把分格加入或移出选择。</td></tr><tr><td>方向键</td><td>按页面 0.2% 微调选中项。</td></tr><tr><td><code>Shift</code> + 方向键</td><td>按 1% 微调。</td></tr><tr><td><code>Delete</code> / <code>Backspace</code></td><td>删除选中的分格（或选中的标注）。</td></tr><tr><td><code>Enter</code></td><td>保存（确认模式）。</td></tr><tr><td><code>Esc</code></td><td>放弃改动（确认模式）；否则退出标注工具或取消选中标注。</td></tr></tbody></table><p>标注工具栏没有字母快捷键，只能用鼠标。<code>Esc</code> 总是后退一级：选中标注 → 当前工具 → 有未保存改动的页面。</p><h2 id="对照阅读" tabindex="-1">对照阅读 <a class="header-anchor" href="#对照阅读" aria-label="Permalink to &quot;对照阅读&quot;">​</a></h2><table tabindex="0"><thead><tr><th>按键 / 手势</th><th>操作</th></tr></thead><tbody><tr><td><code>H</code></td><td>全部遮蔽（打开遮蔽总开关）。</td></tr><tr><td><code>Shift+H</code></td><td>全部显示（关闭遮蔽总开关）。</td></tr><tr><td>拖动某一栏</td><td>平移该语言。</td></tr><tr><td>在某栏上滚轮</td><td>缩放该语言。</td></tr><tr><td><code>Alt</code> + 拖拽 / 滚轮</td><td>只对当前格应用该手势。</td></tr><tr><td>点击已遮蔽的栏</td><td>临时显示；再次点击可重新遮蔽。</td></tr></tbody></table><p>分格导航使用 <strong>上一格</strong> / <strong>下一格</strong> 按钮；它们没有绑定按键，因为 <code>[</code> 和 <code>]</code> 已经用于翻页。</p><h2 id="笔记编辑器" tabindex="-1">笔记编辑器 <a class="header-anchor" href="#笔记编辑器" aria-label="Permalink to &quot;笔记编辑器&quot;">​</a></h2><table tabindex="0"><thead><tr><th>按键</th><th>操作</th></tr></thead><tbody><tr><td><code>Ctrl+B</code></td><td>加粗。</td></tr><tr><td><code>Ctrl+I</code></td><td>斜体。</td></tr><tr><td><code>Ctrl+K</code></td><td>插入链接。</td></tr><tr><td><code>Ctrl+Enter</code></td><td>保存笔记（或保存随手记）。</td></tr><tr><td>标签框里按 <code>Enter</code></td><td>添加标签。</td></tr><tr><td><code>Tab</code></td><td>在编辑器内缩进。</td></tr></tbody></table><h2 id="仅鼠标操作" tabindex="-1">仅鼠标操作 <a class="header-anchor" href="#仅鼠标操作" aria-label="Permalink to &quot;仅鼠标操作&quot;">​</a></h2><p>有些控件按设计没有键盘等价操作：</p><ul><li>分隔条：拖动调整大小，双击恢复默认。</li><li>对照阅读中的语言标签排序：拖动标签。</li><li>缩放按钮：分格工具栏中的 <code>−</code> / <code>＋</code>。</li><li>分格模板与对齐预设选择器。</li></ul><h2 id="常见坑" tabindex="-1">常见坑 <a class="header-anchor" href="#常见坑" aria-label="Permalink to &quot;常见坑&quot;">​</a></h2><ul><li><strong>快捷键却打出了字母。</strong> 焦点在 input、textarea 或 contenteditable 元素中。先点击舞台。</li><li><strong><code>H</code> 不遮蔽。</strong> 焦点在笔记或工具栏输入框中；输入时对照快捷键会被忽略。</li><li><strong><code>E</code> 没反应。</strong> 没有打开的页面，导出对话框不可用。</li><li><strong><code>Ctrl+Z</code> 撤销的是笔记。</strong> 在文本字段内用的是浏览器原生撤销；页面级撤销只在舞台上有效。</li></ul><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li><a href="/KomaYomi-docs/zh/guide/panels">切格工作台</a> —— 这些按键驱动的控件。</li><li><a href="/KomaYomi-docs/zh/guide/compare">对照阅读</a> —— 遮蔽与对齐。</li><li><a href="/KomaYomi-docs/zh/guide/notes">笔记</a> —— 编辑器行为。</li></ul>',24)])])}const p=d(a,[["render",c]]);export{u as __pageData,p as default};
